import{_ as t,a}from"./chunks/rtk_trimble_two_gnss_pinouts.B7yeSXiM.js";import{_ as r,o,c as i,al as l}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"Trimble MB-Two","description":"","frontmatter":{},"headers":[],"relativePath":"uk/gps_compass/rtk_gps_trimble_mb_two.md","filePath":"uk/gps_compass/rtk_gps_trimble_mb_two.md"}'),n={name:"uk/gps_compass/rtk_gps_trimble_mb_two.md"};function s(p,e,d,c,h,m){return o(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="trimble-mb-two" tabindex="-1">Trimble MB-Two <a class="header-anchor" href="#trimble-mb-two" aria-label="Permalink to &quot;Trimble MB-Two&quot;">​</a></h1><p>The <a href="https://oemgnss.trimble.com/en/products/receiver-modules/mb-two" target="_blank" rel="noreferrer">Trimble MB-Two RTK GPS receiver</a> is a high-end, dual-frequency <a href="./../gps_compass/rtk_gps">RTK GPS module</a> that can be configured as either base or rover.</p><p><img src="'+t+'" alt="MB-Two Hero image"></p><h2 id="необхідні-параметри-прошивки" tabindex="-1">Необхідні параметри прошивки <a class="header-anchor" href="#необхідні-параметри-прошивки" aria-label="Permalink to &quot;Необхідні параметри прошивки&quot;">​</a></h2><p>При купівлі пристрою необхідно вибрати наступні параметри вбудованого програмного забезпечення:</p><ul><li>[X] [2] [N] [G] [W] [Y] [J] для оновлень позиції 20 Гц та підтримки RTK, горизонтальна точність позиції 1 см та вертикальна 2 см</li><li>[L] LBAND</li><li>[D] DUO - Напрямок з двома антенами</li><li>[B] BEIDOU + [O] GALILEO, за потреби</li></ul><h2 id="антени-та-кабель" tabindex="-1">Антени та кабель <a class="header-anchor" href="#антени-та-кабель" aria-label="Permalink to &quot;Антени та кабель&quot;">​</a></h2><p>Для Trimble MB-Two потрібні дві двохчастотні (L1/L2) антени. A good example is the <a href="https://www.maxtena.com/products/helicore/m1227hct-a2-sma/" target="_blank" rel="noreferrer">Maxtenna M1227HCT-A2-SMA</a> (which can be bought, for instance, from <a href="https://uk.farnell.com/maxtena/m1227hct-a2-sma/antenna-1-217-1-25-1-565-1-61ghz/dp/2484959" target="_blank" rel="noreferrer">Farnell</a>).</p><p>Тип роз&#39;єму антени на пристрої - MMCX. Підходящі кабелі для вищезазначених антен (коннектор SMA) можна знайти тут:</p><ul><li><a href="https://www.digikey.com/products/en?mpart=415-0073-012&amp;v=24" target="_blank" rel="noreferrer">30 cm version</a></li><li><a href="https://www.digikey.com/products/en?mpart=415-0073-018&amp;v=24" target="_blank" rel="noreferrer">45 cm version</a></li></ul><h2 id="підключення-та-з-єднання" tabindex="-1">Підключення та з&#39;єднання <a class="header-anchor" href="#підключення-та-з-єднання" aria-label="Permalink to &quot;Підключення та з&#39;єднання&quot;">​</a></h2><p>Trimble MB-Two підключений до UART на польотному контролері (порт GPS) для передачі даних.</p><p>Для живлення модуля вам знадобиться окреме джерело живлення 3,3 В (максимальне споживання 360 мА).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The module cannot be powered from a Pixhawk.</p></div><p>Контакти на 28-контактному роз&#39;ємі пронумеровані, як показано нижче:</p><p><img src="'+a+'" alt="MB-Two Pinout"></p><table tabindex="0"><thead><tr><th>Pin</th><th>Назва</th><th>Опис</th></tr></thead><tbody><tr><td>6</td><td>Vcc 3.3V</td><td>Джерело живлення</td></tr><tr><td>14</td><td>GND</td><td>Connect to power the supply and GND of the Autopilot</td></tr><tr><td>15</td><td>TXD1</td><td>Connect to RX of the Autopilot</td></tr><tr><td>16</td><td>RXD1</td><td>Connect to TX of the Autopilot</td></tr></tbody></table><h2 id="налаштування" tabindex="-1">Налаштування <a class="header-anchor" href="#налаштування" aria-label="Permalink to &quot;Налаштування&quot;">​</a></h2><p>First set the GPS protocol to Trimble (<a href="./../advanced_config/parameter_reference#GPS_1_PROTOCOL">GPS_x_PROTOCOL=3</a>).</p><p><a href="./../peripherals/serial_configuration">Configure the serial port</a> on which the Trimple will run using <a href="./../advanced_config/parameter_reference#GPS_1_CONFIG">GPS_1_CONFIG</a>, and set the baud rate to 115200 using <a href="./../advanced_config/parameter_reference#SER_GPS1_BAUD">SER_GPS1_BAUD</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 doesn&#39;t use the MB-Two&#39;s dual-antenna heading.</p></div>',21)])])}const f=r(n,[["render",s]]);export{u as __pageData,f as default};
